mapper.select:
WITH income_summary AS ( SELECT asset_uid, SUM(total_amount) AS income FROM his_equipment_data_result WHERE  tenant_uid=#{tenantUid}

    and  asset_uid IN

        #{item}


and    exec_time  between #{startDate} and #{endDate} GROUP BY asset_uid ),
expense_summary AS ( SELECT asset_uid, SUM(cost_amount) AS cost FROM asset_cost_amount_info WHERE  tenant_uid=#{tenantUid}

    and  asset_uid IN

        #{item}


and    statistical_date  between #{startDate} and #{endDate} GROUP BY asset_uid ),
check_summary AS ( SELECT qr_code, SUM(check_number_people) AS checkNumberPeople FROM iot_performance_info WHERE  tenant_uid=#{tenantUid}

    and  qr_code IN

        #{item}


and    date  between #{startDate} and #{endDate} GROUP BY qr_code )
select es.asset_uid assetUid,  COALESCE(isum.income, 0) AS income, COALESCE(esum.cost, 0) AS cost,COALESCE(csum.checkNumberPeople, 0) AS  checkNumberPeople,ai.name as assetName,ai.serial_num  serialNum , ai.qr_code qrCode,ai.function_type functionType ,ai.purchase_price purchasePrice,ai.clinical_dept_name clinicalDeptName ,ai.asset_group assetGroup,ai.make_short_name as  makerShortName,  ai.id  as assetId,es.positive_rate  as  positiveRate  from  efficiency_equipment_info es join asset_info ai on es.asset_uid=ai.uid
LEFT JOIN income_summary isum ON es.asset_uid = isum.asset_uid LEFT JOIN expense_summary esum ON es.asset_uid = esum.asset_uid LEFT JOIN check_summary csum ON ai.qr_code = csum.qr_code


        and   es.asset_uid IN

            #{item}



        and   (ai.site_uid=#{orgUid}    or ai.hospital_uid=#{orgUid}     or ai.institution_uid=#{orgUid}    or ai.tenant_uid=#{orgUid}        )



        AND (
        ai.institution_uid IN

            #{item}

        OR ai.hospital_uid IN

            #{item}

        OR ai.site_uid IN

            #{item}

        OR ai.clinical_dept_uid IN

            #{item}

        OR ai.asset_dept_uid IN

            #{item}

        OR ai.tenant_uid IN

            #{item}

        )




order by es.uid desc
limit 5000

WITH time_range AS ( SELECT #{startDate}::date AS start_date, #{endDate}::date AS end_date ), income_summary AS ( SELECT asset_uid, SUM(total_amount) AS income FROM his_equipment_data_result WHERE tenant_uid = #{tenantUid} AND exec_time BETWEEN (SELECT start_date FROM time_range) AND (SELECT end_date FROM time_range) GROUP BY asset_uid ), expense_summary AS ( SELECT asset_uid, SUM(cost_amount) AS cost FROM asset_cost_amount_info WHERE tenant_uid = #{tenantUid} AND statistical_date BETWEEN (SELECT start_date FROM time_range) AND (SELECT end_date FROM time_range) GROUP BY asset_uid ), monthly_dates AS ( SELECT asset_id, deprecate_date, deprecate_amount AS dep_amount, deprecate_date AS month_start, (deprecate_date + INTERVAL '1 month - 1 day')::date AS month_end FROM asset_depreciation ), depreciation AS ( SELECT asset_id, SUM( CASE WHEN start_date >= month_start AND start_date <= month_end AND end_date <= month_end THEN dep_amount * (end_date - start_date + 1) / (month_end - month_start + 1) WHEN start_date >= month_start AND start_date <= month_end THEN dep_amount * (month_end - start_date + 1) / (month_end - month_start + 1) WHEN end_date >= month_start AND end_date <= month_end THEN dep_amount * (end_date - month_start + 1) / (month_end - month_start + 1) WHEN start_date <= month_start AND end_date >= month_end THEN dep_amount ELSE 0 END ) AS total_depreciation FROM monthly_dates JOIN time_range ON TRUE GROUP BY asset_id ), result AS ( SELECT e.uid as uid, e.asset_uid AS assetUid, COALESCE(income.income, 0) AS income, COALESCE(expense.cost, 0) AS entryCost, COALESCE(d.total_depreciation, 0) AS depreciation, COALESCE(expense.cost, 0) +COALESCE(d.total_depreciation, 0) as cost, ai.NAME AS assetName, ai.serial_num AS serialNum, ai.qr_code AS qrCode, ai.function_type AS functionType, ai.purchase_price AS purchasePrice, ai.clinical_dept_name AS clinicalDeptName, ai.asset_dept_uid AS assetDeptUID, ai.asset_dept_name AS assetDeptName, ai.asset_group AS assetGroup, ai.make_short_name AS makerShortName, ai.id AS assetId, ai.financing_num as financingNum, ai.purchase_date as purchaseDate, e.positive_rate AS positiveRate, e.display_name AS displayName, (COALESCE(income.income, 0) - COALESCE(expense.cost, 0) - COALESCE(d.total_depreciation, 0)) AS profits, CASE WHEN COALESCE(income.income, 0) = 0 THEN 0 ELSE (COALESCE(income.income, 0) - COALESCE(expense.cost, 0) - COALESCE(d.total_depreciation, 0)) / COALESCE(income.income, 0) * 100 END AS profitsRate FROM efficiency_equipment_info e LEFT JOIN asset_info ai ON e.asset_uid = ai.uid LEFT JOIN income_summary income ON e.asset_uid = income.asset_uid LEFT JOIN expense_summary expense ON e.asset_uid = expense.asset_uid LEFT JOIN depreciation d ON ai.id = d.asset_id
where ai.tenant_uid=#{tenantUid} and ai.is_valid =true
AND ( ai.institution_uid = #{selectedOrgUid} OR ai.hospital_uid = #{selectedOrgUid} OR ai.site_uid = #{selectedOrgUid} )
AND ( ai.institution_uid IN
#{item}
OR ai.hospital_uid IN
#{item}
OR ai.site_uid IN
#{item}
OR ai.clinical_dept_uid IN
#{item}
OR ai.asset_dept_uid IN
#{item}
)
AND ai.clinical_dept_uid IN
#{item}
AND ai.asset_dept_uid IN
#{item}
and e.asset_uid IN
#{item}
AND ai.name like concat('%',#{assetName},'%')
AND e.display_name like concat('%',#{displayName},'%')
AND ai.serial_num like concat('%',#{serialNum},'%')
AND ai.financing_num like concat('%',#{financingNum},'%')
AND ai.clinical_dept_name like concat('%',#{clinicalDeptName},'%')
AND ai.qr_code like concat('%',#{qrCode},'%')
AND ai.asset_group =#{assetGroup}
AND ai.depart_num like concat('%',#{departNum},'%')
AND ai.function_type like concat('%',#{functionType},'%')
AND ai.financing_num like concat('%',#{financingNum},'%')
AND ai.make_short_name like concat('%',#{makerShortName},'%')
and ai.purchase_date >= #{purchaseDateGTE}
and ai.purchase_date <= #{purchaseDateLTE}
) SELECT * FROM result r
and r.purchasePrice>=#{purchasePriceGTE}
and r.purchasePrice <= #{purchasePriceLTE}
and r.income>=#{incomeGTE}
and r.income <= #{incomeLTE}
and r.income>=#{incomeGTE}
and r.income <= #{incomeLTE}
and r.cost>=#{costGTE}
and r.cost <= #{costLTE}
and r.profits>=#{profitsGTE}
and r.profits <= #{profitsLTE}
and r.profitsRate>=#{profitsRateGTE}
and r.profitsRate <= #{profitsRateLTE}
and r.positiveRate>=#{positiveRateGTE}
and r.positiveRate <= #{positiveRateLTE}
ORDER BY ${orderBy}
LIMIT #{page} OFFSET #{offset}

