LESCE(income.income, 0) - COALESCE(expense.cost, 0) - COALESCE(d.total_depreciation, 0)) AS profits, CASE WHEN COALESCE(income.income, 0) = 0 THEN 0 ELSE (COALESCE(income.income, 0) - COALESCE(expense.cost, 0) - COALESCE(d.total_depreciation, 0)) / COALESCE(income.income, 0) * 100 END AS profitsRate FROM efficiency_equipment_info e LEFT JOIN asset_info ai ON e.asset_uid = ai.uid LEFT JOIN income_summary income ON e.asset_uid = income.asset_uid LEFT JOIN expense_summary expense ON e.asset_uid = expense.asset_uid LEFT JOIN depreciation d ON ai.id = d.asset_id
